-- composition of rule kernels disjunctive_join_rewriter x empty_result_pullup (duckdb), template union
SELECT count(*) FROM (SELECT 1 AS k FROM (SELECT '2024-01-01'::date AS c0, (MAX ('epoch'::timestamptz) OVER () + '00:00:00.000001'::interval) AS c1 FROM tp AS a1 WHERE FALSE) AS ka UNION ALL SELECT 2 AS k FROM (FROM (VALUES (1, 2)) a(x, y) JOIN (VALUES (1, 2)) b( y) ON a.x JOIN (VALUES (1, 2)) c(x, y) ON a.x = c.x OR a.y = c.y) AS kb) AS u;
